class Solution {
public:
    int distMoney(int money, int children) {
        // Each child must receive at least $1.
        if (money < children)
            return -1;

        // Give $1 to every child first.
        money -= children;

        // Each $8 child needs $7 more.
        int count = min(money / 7, children);

        money -= count * 7;

        // If everyone has $8 but money remains,
        // one child must receive more than $8.
        if (count == children && money > 0)
            return children - 1;

        // If exactly one child remains and has $4,
        // reduce the number of $8 children.
        if (count == children - 1 && money == 3)
            return count - 1;

        return count;
    }
};
